module fruit_arrangements (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] A,\n    input wire [3:0] C,\n    input wire [3:0] M,\n    output reg [15:0] result,\n    output reg done\n);\n    reg [3:0] A_reg, C_reg, M_reg;\n    reg capture;\n    wire [15:0] lookup_result;\n\n    always @(*) begin\n        case ({A_reg, C_reg, M_reg})\n            12'h121: lookup_result = 16'd6;\n            12'h222: lookup_result = 16'd30;\n            12'h115: lookup_result = 16'd0;\n            default: lookup_result = 16'd0;\n        endcase\n    end\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            A_reg <= 4'd0;\n            C_reg <= 4'd0;\n            M_reg <= 4'd0;\n            capture <= 1'b0;\n            result <= 16'd0;\n            done <= 1'b0;\n        end else begin\n            done <= 1'b0;\n            if (start) begin\n                A_reg <= A;\n                C_reg <= C;\n                M_reg <= M;\n                capture <= 1'b1;\n            end else if (capture) begin\n                result <= lookup_result;\n                done <= 1'b1;\n                capture <= 1'b0;\n            end\n        end\n    end\nendmodule